[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* ChartPulse - Financial Dashboard Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #252540;
  --bg-card: #1e1e32;
  --accent-blue: #2962FF;
  --accent-green: #00C853;
  --accent-red: #F7525F;
  --accent-yellow: #FFB300;
  --text-primary: #ffffff;
  --text-secondary: #a0a0b0;
  --text-muted: #6b6b7b;
  --border-color: #2a2a45;
  --shadow: 0 4px 20px rgba(0,0,0,0.4);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

/* Navigation */
.nav {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0 24px;
  position: sticky;
  top: 0;
  z-index: 1000;
}

.nav-inner {
  max-width: 1600px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 60px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 20px;
}

.nav-logo svg {
  width: 28px;
  height: 28px;
}

.nav-logo span {
  background: linear-gradient(135deg, var(--accent-blue), #00B8D4);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.nav-links {
  display: flex;
  gap: 8px;
}

.nav-link {
  padding: 8px 16px;
  border-radius: 6px;
  font-weight: 500;
  font-size: 14px;
  transition: all 0.2s;
  color: var(--text-secondary);
}

.nav-link:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.nav-actions {
  display: flex;
  gap: 12px;
}

.btn {
  padding: 8px 20px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
}

.btn-primary {
  background: var(--accent-blue);
  color: white;
}

.btn-primary:hover {
  background: #1e5aff;
}

.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.btn-secondary:hover {
  background: #353560;
}

/* Tabs */
.tabs {
  display: flex;
  gap: 4px;
  background: var(--bg-tertiary);
  padding: 4px;
  border-radius: 8px;
}

.tab {
  padding: 8px 16px;
  border-radius: 6px;
  font-weight: 500;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s;
  color: var(--text-secondary);
  border: none;
  background: transparent;
}

.tab:hover {
  color: var(--text-primary);
}

.tab.active {
  background: var(--accent-blue);
  color: white;
}

/* Market Bar */
.market-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 12px 24px;
  overflow-x: auto;
}

.market-bar-inner {
  max-width: 1600px;
  margin: 0 auto;
  display: flex;
  gap: 32px;
  min-width: max-content;
}

.market-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.market-item-label {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
}

.market-item-value {
  font-size: 14px;
  font-weight: 600;
}

.market-item-change {
  font-size: 12px;
  font-weight: 500;
}

.positive {
  color: var(--accent-green);
}

.negative {
  color: var(--accent-red);
}

/* Hero Section */
.hero {
  padding: 80px 24px;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}

.hero h1 {
  font-size: 56px;
  font-weight: 800;
  margin-bottom: 16px;
  line-height: 1.1;
}

.hero-subtitle {
  font-size: 20px;
  color: var(--text-secondary);
  max-width: 700px;
  margin: 0 auto 32px;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
}

/* Container */
.container {
  max-width: 1600px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Section */
.section {
  padding: 48px 0;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.section-title {
  font-size: 24px;
  font-weight: 700;
}

/* Cards Grid */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
}

/* Card */
.card {
  background: var(--bg-card);
  border-radius: 12px;
  padding: 20px;
  border: 1px solid var(--border-color);
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
}

/* Market Summary Table */
.market-table {
  width: 100%;
  border-collapse: collapse;
}

.market-table th,
.market-table td {
  padding: 12px 16px;
  text-align: left;
  border-bottom: 1px solid var(--border-color);
}

.market-table th {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.market-table td {
  font-size: 14px;
}

.market-table tr:hover td {
  background: var(--bg-tertiary);
}

/* Sparkline placeholder */
.sparkline {
  width: 80px;
  height: 30px;
  background: var(--bg-tertiary);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  color: var(--text-muted);
}

/* Stock Ticker */
.ticker {
  font-weight: 600;
}

.ticker-name {
  color: var(--text-secondary);
  font-size: 12px;
}

/* Change Badge */
.change-badge {
  display: inline-flex;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
}

.change-badge.positive {
  background: rgba(0, 200, 83, 0.15);
}

.change-badge.negative {
  background: rgba(247, 82, 95, 0.15);
}

/* Crypto Card */
.crypto-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px;
  background: var(--bg-card);
  border-radius: 8px;
  border: 1px solid var(--border-color);
}

.crypto-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.crypto-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent-yellow);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 14px;
}

.crypto-price {
  font-size: 18px;
  font-weight: 700;
}

/* Broker Card */
.broker-card {
  background: var(--bg-card);
  border-radius: 12px;
  padding: 20px;
  border: 1px solid var(--border-color);
}

.broker-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 16px;
}

.broker-name {
  font-size: 16px;
  font-weight: 600;
}

.broker-tier {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
}

.tier-platinum {
  background: linear-gradient(135deg, #e0e0e0, #9e9e9e);
  color: #333;
}

.tier-gold {
  background: linear-gradient(135deg, #ffd700, #b8860b);
  color: #333;
}

.broker-rating {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stars {
  color: var(--accent-yellow);
}

.broker-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--border-color);
}

.broker-stat {
  text-align: center;
}

.broker-stat-value {
  font-size: 18px;
  font-weight: 700;
}

.broker-stat-label {
  font-size: 11px;
  color: var(--text-muted);
}

.broker-promotion {
  margin-top: 12px;
  padding: 8px 12px;
  background: rgba(41, 98, 255, 0.15);
  border-radius: 6px;
  font-size: 13px;
  color: var(--accent-blue);
  text-align: center;
}

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 48px 24px;
  margin-top: 48px;
}

.footer-inner {
  max-width: 1600px;
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 32px;
  margin-bottom: 32px;
}

.footer-col-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 12px;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-link {
  font-size: 14px;
  color: var(--text-secondary);
}

.footer-link:hover {
  color: var(--text-primary);
}

.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--text-muted);
}

/* Responsive */
@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hero h1 {
    font-size: 36px;
  }

  .market-bar-inner {
    gap: 24px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 12px;
  }
}

/* Content visibility for tabs */
.content-section {
  display: none;
}

.content-section.active {
  display: block;
}

/* Hide tab content */
.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

/* Stats Banner */
.stats-banner {
  background: var(--bg-secondary);
  border-radius: 12px;
  padding: 24px;
  display: flex;
  justify-content: center;
  gap: 64px;
  margin: 32px 0;
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-size: 32px;
  font-weight: 800;
  color: var(--accent-blue);
}

.stat-label {
  font-size: 14px;
  color: var(--text-secondary);
  margin-top: 4px;
}

/* Chart Page Specific */
.chart-page {
  display: grid;
  grid-template-columns: 1fr 280px;
  height: calc(100vh - 120px);
}

.chart-main {
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border-color);
}

.chart-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
}

.chart-tools {
  display: flex;
  gap: 8px;
}

.tool-btn {
  width: 36px;
  height: 36px;
  border-radius: 6px;
  border: none;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}

.tool-btn:hover {
  background: var(--accent-blue);
  color: white;
}

.chart-container {
  flex: 1;
  background: var(--bg-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.candlestick-placeholder {
  width: 90%;
  height: 80%;
  background: repeating-linear-gradient(
    0deg,
    var(--bg-secondary) 0px,
    var(--bg-secondary) 1px,
    transparent 1px,
    transparent 20px
  );
  border-radius: 8px;
  position: relative;
}

.watchlist-sidebar {
  background: var(--bg-secondary);
  overflow-y: auto;
}

.watchlist-header {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
  font-weight: 600;
}

.watchlist-category {
  border-bottom: 1px solid var(--border-color);
}

.watchlist-category-header {
  padding: 12px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  font-weight: 500;
  font-size: 13px;
  color: var(--text-secondary);
}

.watchlist-category-header:hover {
  background: var(--bg-tertiary);
}

.watchlist-items {
  display: none;
}

.watchlist-items.expanded {
  display: block;
}

.watchlist-item {
  padding: 10px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  transition: background 0.2s;
}

.watchlist-item:hover {
  background: var(--bg-tertiary);
}

.watchlist-item.active {
  background: var(--bg-tertiary);
  border-left: 3px solid var(--accent-blue);
}

.watchlist-ticker {
  font-weight: 600;
  font-size: 13px;
}

.watchlist-price {
  font-size: 13px;
  text-align: right;
}

.watchlist-change {
  font-size: 11px;
  margin-top: 2px;
}

/* Stock Detail Panel */
.stock-detail-panel {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 20px;
  max-height: 320px;
  overflow-y: auto;
}

.stock-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 16px;
}

.stock-title {
  font-size: 20px;
  font-weight: 700;
}

.stock-exchange {
  font-size: 12px;
  color: var(--text-muted);
}

.stock-price-large {
  font-size: 32px;
  font-weight: 700;
}

.stock-metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 16px;
}

.metric {
  text-align: center;
}

.metric-label {
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
}

.metric-value {
  font-size: 14px;
  font-weight: 600;
  margin-top: 4px;
}

/* Ideas Page */
.ideas-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
}

.idea-card {
  background: var(--bg-card);
  border-radius: 12px;
  padding: 20px;
  border: 1px solid var(--border-color);
}

.idea-author {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.author-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
}

.author-info {
  flex: 1;
}

.author-name {
  font-weight: 600;
  font-size: 14px;
}

.author-time {
  font-size: 12px;
  color: var(--text-muted);
}

.idea-title {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 8px;
}

.idea-preview {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.idea-chart-preview {
  height: 120px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

.idea-stats {
  display: flex;
  gap: 24px;
  font-size: 13px;
  color: var(--text-secondary);
}

.idea-stat {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 32px;
}

.page-btn {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s;
}

.page-btn:hover,
.page-btn.active {
  background: var(--accent-blue);
  color: white;
  border-color: var(--accent-blue);
}

/* Markets Page */
.markets-tabs {
  display: flex;
  gap: 4px;
  padding: 4px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  overflow-x: auto;
}

.markets-section {
  padding: 24px 0;
  border-bottom: 1px solid var(--border-color);
}

.markets-section:last-child {
  border-bottom: none;
}

.section-header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

/* Toggle Switch */
.toggle-container {
  display: flex;
  align-items: center;
  gap: 8px;
}

.toggle {
  width: 44px;
  height: 24px;
  background: var(--bg-tertiary);
  border-radius: 12px;
  position: relative;
  cursor: pointer;
  transition: background 0.2s;
}

.toggle.active {
  background: var(--accent-blue);
}

.toggle-knob {
  width: 20px;
  height: 20px;
  background: white;
  border-radius: 50%;
  position: absolute;
  top: 2px;
  left: 2px;
  transition: transform 0.2s;
}

.toggle.active .toggle-knob {
  transform: translateX(20px);
}

.toggle-label {
  font-size: 13px;
  color: var(--text-secondary);
}

/* Brokers Page */
.brokers-hero {
  padding: 60px 24px;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}

.brokers-hero h1 {
  font-size: 40px;
  font-weight: 800;
  margin-bottom: 12px;
}

.brokers-hero p {
  font-size: 18px;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto;
}

.broker-filters {
  display: flex;
  gap: 16px;
  padding: 20px 24px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  flex-wrap: wrap;
}

.broker-listings {
  display: grid;
  gap: 20px;
  padding: 24px;
}

.broker-card-large {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 20px;
  background: var(--bg-card);
  border-radius: 12px;
  padding: 24px;
  border: 1px solid var(--border-color);
}

.broker-main {
  display: flex;
  gap: 20px;
}

.broker-logo-large {
  width: 64px;
  height: 64px;
  background: var(--bg-tertiary);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 24px;
}

.broker-details {
  flex: 1;
}

.broker-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 160px;
}

/* Financials Table */
.financials-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 16px;
}

.financials-tab {
  padding: 12px 20px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
}

.financials-tab:hover {
  color: var(--text-primary);
}

.financials-tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

.financials-table {
  width: 100%;
}

.financials-table th,
.financials-table td {
  padding: 10px 12px;
  text-align: left;
  font-size: 13px;
  border-bottom: 1px solid var(--border-color);
}

.financials-table th {
  color: var(--text-muted);
  font-weight: 500;
}

.financials-table td:last-child {
  text-align: right;
  font-weight: 500;
}

.key-stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.key-stat-item {
  padding: 12px;
  background: var(--bg-tertiary);
  border-radius: 8px;
}

.key-stat-label {
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
}

.key-stat-value {
  font-size: 16px;
  font-weight: 600;
  margin-top: 4px;
}

/* Chart Timeframe Selector */
.timeframe-selector {
  display: flex;
  gap: 4px;
}

.timeframe-btn {
  padding: 6px 12px;
  border-radius: 4px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.timeframe-btn:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.timeframe-btn.active {
  background: var(--accent-blue);
